#[test]
fn bindgen_test_layout_arm64_op_mem() {
    const UNINIT: ::std::mem::MaybeUninit<arm64_op_mem> = ::std::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::std::mem::size_of::<arm64_op_mem>(),
        12usize,
        concat!("Size of: ", stringify!(arm64_op_mem))
    );
    assert_eq!(
        ::std::mem::align_of::<arm64_op_mem>(),
        4usize,
        concat!("Alignment of ", stringify!(arm64_op_mem))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).base) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(arm64_op_mem),
            "::",
            stringify!(base)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).index) as usize - ptr as usize },
        4usize,
        concat!(
            "Offset of field: ",
            stringify!(arm64_op_mem),
            "::",
            stringify!(index)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).disp) as usize - ptr as usize },
        8usize,
        concat!(
            "Offset of field: ",
            stringify!(arm64_op_mem),
            "::",
            stringify!(disp)
        )
    );
}
